import java.util.*;

class Solution {
    public int[] mergeSorted(int[] x, int[] y) {
        int[] res = new int[x.length + y.length];
        int i = 0, j = 0, k = 0;
        while (i < x.length && j < y.length) {
            if (x[i] <= y[j]) res[k++] = x[i++]; // take the smaller front value
            else res[k++] = y[j++];
        }
        while (i < x.length) res[k++] = x[i++]; // leftover of x
        while (j < y.length) res[k++] = y[j++]; // leftover of y
        return res;
    }
}

