class Solution:
    def mergeSorted(self, x: List[int], y: List[int]) -> List[int]:
        i = j = 0; out = []
        while i < len(x) and j < len(y):
            if x[i] <= y[j]: out.append(x[i]); i += 1
            else: out.append(y[j]); j += 1
        return out + x[i:] + y[j:]

